INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Section 501(h) expenditure election and excise tax on excess lobbying
(3, 'Tax-Exempt Organizations', 'Bright Horizon Charity, a 501(c)(3) with $400,000 in exempt purpose expenditures, makes the Section 501(h) election. The lobbying nontaxable amount is 20% of the first $500,000, giving Bright Horizon an $80,000 ceiling. The organization spends $90,000 on lobbying during 2026. What is the tax consequence of exceeding the lobbying nontaxable amount?', '["Bright Horizon automatically loses its exempt status for exceeding the limit", "No consequence arises because the 501(h) election exempts all lobbying from penalty", "A 25% excise tax is imposed on the $10,000 excess lobbying expenditure under Section 4911", "The $10,000 excess is treated as unrelated business income subject to UBIT"]'::jsonb, 2, 'Under IRC Section 4911, organizations electing the Section 501(h) expenditure test that exceed their lobbying nontaxable amount face a 25% excise tax on the excess. For $400,000 in exempt purpose expenditures, the limit is $80,000 (20% of first $500,000). The $10,000 excess triggers a $2,500 excise tax. Unlike choice A, exceeding the limit does not automatically revoke exempt status unless lobbying normally exceeds 150% of the nontaxable amount over a four-year averaging period.', 'medium', 3),

-- Q2: medium / L2 — Supporting organization classification under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Foundation Support Services, a 501(c)(3), is operated exclusively to fundraise and provide administrative services for three public charities: a community hospital, a local university, and a food bank. It does not receive broad public support. How is this organization classified?', '["Private foundation subject to Sections 4940-4945 excise taxes", "Public charity as a supporting organization under Section 509(a)(3)", "Tax-exempt social welfare organization under Section 501(c)(4)", "Private operating foundation exempt from minimum distribution requirements"]'::jsonb, 1, 'Under IRC Section 509(a)(3), an organization operated exclusively to support one or more public charities qualifies as a supporting organization, which is a type of public charity. Foundation Support Services meets this test because it operates solely to benefit three public charities. Unlike choice A, the organization escapes private foundation classification because the 509(a)(3) supporting organization exception applies despite the absence of broad public support.', 'medium', 2),

-- Q3: easy / L1 — Dissolution clause requirement for organizational test
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s governing documents provide regarding asset distribution upon dissolution?', '["Assets must be distributed to another exempt organization or to the government", "Assets must be distributed equally among the organization''s members", "Assets must be returned to original donors in proportion to their contributions", "Assets must be held in trust for five years before any distribution"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the organizational test requires that governing documents include a dissolution clause providing that assets will be distributed to another exempt organization or to the government upon dissolution. This prevents private benefit from the organization''s accumulated assets. Unlike choice B, distribution to members would violate the private inurement prohibition and fail the organizational test.', 'easy', 1),

-- Q4: medium / L2 — Controlled entity payments treated as UBIT
(3, 'Tax-Exempt Organizations', 'Mercy Health Foundation, a 501(c)(3), owns 90% of a for-profit medical supply company. The subsidiary pays $200,000 in annual rent to the foundation for warehouse space. The fair market value of the rental is $150,000. How is the $200,000 rent payment treated for UBIT purposes?', '["Entirely excluded from UBIT because rents from real property are always passive income", "Excluded from UBIT because the subsidiary performs a related exempt function", "Subject to UBIT in full because any payment from a subsidiary is unrelated business income", "Subject to UBIT to the extent the $200,000 exceeds the $150,000 fair market value"]'::jsonb, 3, 'Under IRC Section 512(b)(13), rent, interest, or royalties received from a controlled subsidiary (80% or more ownership) are treated as UBIT to the extent they exceed fair market value. The $50,000 excess ($200,000 minus $150,000 FMV) is subject to UBIT. Unlike choice A, the general exclusion for real property rents does not apply to above-market payments from controlled entities, which are designed to shift income to tax-exempt status.', 'medium', 2),

-- Q5: medium / L2 — Form 990-EZ filing thresholds
(3, 'Tax-Exempt Organizations', 'Green Valley Community Center, a 501(c)(3), had gross receipts of $175,000 and total assets of $450,000 for the 2025 tax year. Which annual information return must Green Valley file with the IRS?', '["Form 990-N (e-Postcard) because gross receipts are under $200,000", "Form 990-EZ because gross receipts are under $200,000 and total assets are under $500,000", "Form 990 (full return) because total assets exceed $200,000", "No return is required because the organization is a small public charity"]'::jsonb, 1, 'Under IRC Section 6033, a tax-exempt organization may file Form 990-EZ if its gross receipts are less than $200,000 AND total assets are less than $500,000. Green Valley meets both thresholds ($175,000 and $450,000). Unlike choice C, the full Form 990 is required only when gross receipts reach $200,000 or more OR total assets reach $500,000 or more. Form 990-N is limited to organizations with gross receipts of $50,000 or less.', 'medium', 2),

-- Q6: easy / L1 — Private inurement prohibition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition prevent in a 501(c)(3) organization?', '["The organization from earning any revenue from commercial activities", "The organization from accumulating a financial reserve for future operations", "Any part of net earnings from benefiting private shareholders or insiders", "The organization from compensating its employees at any level"]'::jsonb, 2, 'Under IRC Section 501(c)(3), the private inurement prohibition prevents any part of an organization''s net earnings from inuring to the benefit of any private shareholder or individual, meaning insiders such as founders, officers, or directors. Unlike choice D, the prohibition does not ban all compensation. Organizations may pay reasonable compensation for services rendered. The prohibition targets excessive or unjustified financial benefits flowing to insiders.', 'easy', 1),

-- Q7: hard / L4 — Debt/basis ratio calculation for UBIT on debt-financed property
(3, 'Tax-Exempt Organizations', 'Riverdale Education Trust, a 501(c)(3), purchases a commercial office building for $2,000,000 using a $1,200,000 mortgage. The building''s average adjusted basis during the year is $1,800,000 and average acquisition indebtedness is $1,100,000. Net rental income from unrelated commercial tenants is $180,000. Apply the Section 514 debt-financed property rules to determine the rental income subject to UBIT and evaluate whether paying down the mortgage would reduce UBIT exposure.', '["$180,000 is fully subject to UBIT because the building is encumbered by any amount of debt", "$73,333 is subject to UBIT, calculated as $1,200,000 divided by $1,800,000 times $180,000", "No rental income is subject to UBIT because rents from real property are excluded as passive income", "$110,000 is subject to UBIT, calculated as $1,100,000 divided by $1,800,000 times $180,000, and reducing the mortgage would proportionally decrease UBIT exposure"]'::jsonb, 3, 'Under IRC Section 514, debt-financed income is subject to UBIT in proportion to the average acquisition indebtedness divided by the average adjusted basis. The ratio is $1,100,000 / $1,800,000 = 61.11%. Applying this to $180,000 yields approximately $110,000 subject to UBIT. Unlike choice C, the passive income exclusion for real property rents does not apply to debt-financed property. Reducing the mortgage directly lowers the debt/basis ratio, proportionally reducing future UBIT exposure.', 'hard', 4),

-- Q8: medium / L3 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Eastwood University, a 501(c)(3), operates a research laboratory that conducts contract research for the federal government generating $300,000 and for a private pharmaceutical company generating $200,000 annually. Apply the UBIT research exclusion to determine which income is excluded.', '["The $300,000 from government research is excluded, and the $200,000 from private research is also excluded because all research by a college or university qualifies for the exclusion", "All $500,000 is subject to UBIT because contract research is inherently a commercial trade or business", "Only the first $1,000 of research income is excluded under the specific deduction provision", "Only government research qualifies for the exclusion while all private contract research is automatically taxable"]'::jsonb, 0, 'Under IRC Sections 512(b)(7)-(9), research performed for the U.S. government is excluded from UBIT, and all research performed by a college or university is also excluded regardless of the funding source. Therefore both the $300,000 and $200,000 qualify for exclusion. Unlike choice D, the university research exclusion applies broadly to all research conducted by colleges and universities, not only government-funded research.', 'medium', 3),

-- Q9: medium / L2 — Filing deadline for Form 990
(3, 'Tax-Exempt Organizations', 'Sunset Arts Alliance, a calendar-year 501(c)(3), needs to determine its 2025 Form 990 filing deadline. The organization''s fiscal year ends December 31. By what date must Sunset Arts Alliance file its Form 990?', '["March 15, 2026, the 15th day of the 3rd month after year-end", "April 15, 2026, matching the individual income tax filing deadline", "May 15, 2026, the 15th day of the 5th month after year-end", "June 15, 2026, the 15th day of the 6th month after year-end"]'::jsonb, 2, 'Under IRC Section 6033, the annual information return (Form 990) is due on the 15th day of the 5th month after the close of the organization''s tax year. For a calendar-year organization, this is May 15. Unlike choice A, the March 15 deadline applies to partnerships and S corporations, not tax-exempt organizations. Extensions of up to six months are available using Form 8868.', 'medium', 2),

-- Q10: medium / L3 — Personal property rents included in UBIT when exceeding 10% threshold
(3, 'Tax-Exempt Organizations', 'Heritage Historical Society, a 501(c)(3), leases a building to a commercial tenant for $10,000 per month. The lease also includes office furniture and equipment at $3,000 per month, making personal property 23% of total rents. Apply the UBIT rules to determine how this mixed rental income is treated.', '["All $13,000 monthly is excluded from UBIT as passive rental income", "The $3,000 personal property rent exceeds 10% of total rents, making all $13,000 per month subject to UBIT", "Only the $3,000 personal property portion is subject to UBIT while the real property rent remains excluded", "All rental income is subject to UBIT because leasing property is always an unrelated business"]'::jsonb, 1, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included. When personal property is leased with real property and the personal property portion exceeds 10% of total rents, the entire rental amount becomes UBIT. Here personal property is 23% ($3,000 / $13,000), exceeding the 10% threshold, so all $13,000 monthly is subject to UBIT. Unlike choice C, the 10% threshold is an all-or-nothing rule, not a proportional split.', 'medium', 3),

-- Q11: medium / L3 — Convenience exclusion for UBIT
(3, 'Tax-Exempt Organizations', 'Oakwood University, a 501(c)(3), operates a cafeteria serving meals exclusively to enrolled students and faculty on campus during the academic year. The cafeteria generates $250,000 in net income annually. A local restaurant owner argues the university has an unfair competitive advantage. Apply the UBIT convenience exclusion to evaluate whether the cafeteria income is taxable.', '["The cafeteria income is fully subject to UBIT because selling meals is a commercial activity", "The income is subject to UBIT but qualifies for the $1,000 specific deduction only", "The income is excluded from UBIT under the research exclusion because it supports education", "The income is excluded from UBIT under the convenience exclusion because it serves students and employees"]'::jsonb, 3, 'Under IRC Section 513(a)(2), a trade or business conducted for the convenience of members, students, patients, or employees is excluded from UBIT. Oakwood''s cafeteria serves exclusively enrolled students and faculty on campus, satisfying the convenience exclusion. Unlike choice A, even though selling meals is a commercial activity, the statutory convenience exclusion overrides the three-part UBIT test when the activity serves the organization''s own constituents.', 'medium', 3),

-- Q12: hard / L3 — Section 4945 taxable expenditures for grants to non-charities without expenditure responsibility
(3, 'Tax-Exempt Organizations', 'Palmer Family Foundation, a private foundation, makes a $100,000 grant to a 501(c)(4) social welfare organization to fund community health programs. The foundation does not exercise expenditure responsibility over the grant and does not verify how the funds are used. Apply the Section 4945 taxable expenditure rules to determine the tax consequences.', '["The grant is a taxable expenditure because the foundation failed to exercise expenditure responsibility over a grant to a non-501(c)(3), triggering a 20% tax on the foundation and 5% on any knowing manager", "The grant is not a taxable expenditure because health programs are charitable regardless of the recipient classification", "The grant triggers only the Section 4940 net investment income tax of 1.39%", "No penalty applies because 501(c)(4) organizations are exempt entities closely related to 501(c)(3) charities"]'::jsonb, 0, 'Under IRC Section 4945(d)(4), grants by a private foundation to organizations other than 501(c)(3) public charities are taxable expenditures unless the foundation exercises expenditure responsibility. A 501(c)(4) is not a 501(c)(3), so the grant requires expenditure responsibility. The initial tax is 20% on the foundation ($20,000) and 5% on any knowing manager ($5,000). Unlike choice D, 501(c)(4) status does not exempt the grant from expenditure responsibility requirements.', 'hard', 3),

-- Q13: easy / L1 — Form 990-N (e-Postcard) threshold
(3, 'Tax-Exempt Organizations', 'What is the maximum gross receipts threshold for filing Form 990-N (e-Postcard)?', '["$25,000 or less in annual gross receipts", "$50,000 or less in annual gross receipts", "$100,000 or less in annual gross receipts", "$200,000 or less in annual gross receipts"]'::jsonb, 1, 'Under IRC Section 6033, tax-exempt organizations with gross receipts normally $50,000 or less may file Form 990-N, an electronic notice requiring only basic information such as name, address, and EIN. Unlike choice D, the $200,000 threshold relates to Form 990-EZ eligibility (combined with total assets under $500,000), not the simplified e-Postcard filing option available to the smallest exempt organizations.', 'easy', 1),

-- Q14: easy / L1 — Form 990-PF required for all private foundations
(3, 'Tax-Exempt Organizations', 'Which annual return must all private foundations file regardless of their size or financial activity?', '["Form 990 with Schedule A attached", "Form 990-EZ with a supplemental investment schedule", "Form 990-N (e-Postcard) if gross receipts are under $50,000", "Form 990-PF, which includes excise tax computations"]'::jsonb, 3, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of their size, gross receipts, or total assets. This detailed return includes computation of excise taxes under Sections 4940-4945. Unlike choice C, private foundations cannot use the simplified e-Postcard filing. The 990-PF requirement applies universally to ensure transparency and excise tax compliance for all private foundations.', 'easy', 1),

-- Q15: easy / L1 — Bingo exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under what condition is income from bingo games excluded from UBIT for a tax-exempt organization?', '["Bingo income is always subject to UBIT regardless of circumstances", "Bingo is excluded only if the organization uses all proceeds for charitable purposes", "Bingo is excluded if it is legal and commercial bingo is not ordinarily carried on in the jurisdiction", "Bingo is excluded only when played fewer than 12 times per year"]'::jsonb, 2, 'Under IRC Section 513(f), income from bingo games is excluded from UBIT if the bingo game is legal under state and local law and commercial bingo is not ordinarily carried on in the same jurisdiction. Unlike choice A, Congress specifically carved out bingo games as a statutory exclusion from UBIT, recognizing their traditional role in nonprofit fundraising when they do not compete with commercial bingo operations.', 'easy', 1),

-- Q16: hard / L4 — Additional 200% tax on excess benefit not corrected under Section 4958
(3, 'Tax-Exempt Organizations', 'Crossroads Community Foundation, a 501(c)(3), pays its CFO, a disqualified person, a $180,000 bonus later determined to be an excess benefit. The CFO fails to return the excess within the taxable period. The board treasurer approved the bonus knowing it was unreasonable. Evaluate the total excise tax exposure for both the CFO and the treasurer under Section 4958 intermediate sanctions.', '["The CFO faces a 25% initial tax ($45,000) plus a 200% additional tax ($360,000) for failure to correct, totaling $405,000; the treasurer faces a 10% tax capped at $20,000", "The CFO faces only the 25% initial tax because the 200% additional tax requires a court order", "The foundation itself is subject to revocation but neither individual faces personal excise taxes", "Both the CFO and treasurer face identical 25% taxes on the excess benefit"]'::jsonb, 0, 'Under IRC Section 4958, the disqualified person (CFO) faces a 25% initial tax on the excess benefit ($45,000) and, if not corrected within the taxable period, a 200% additional tax ($360,000). The knowing manager (treasurer) faces a 10% tax capped at $20,000 per transaction. Unlike choice B, the 200% additional tax is triggered automatically by failure to correct and requires no court order. Total CFO exposure is $405,000; treasurer exposure is $18,000 (10% of $180,000, under the cap).', 'hard', 4),

-- Q17: medium / L3 — Excess business holdings combined with disqualified persons under Section 4943
(3, 'Tax-Exempt Organizations', 'Turner Family Foundation, a private foundation, owns 12% of the voting stock of a publicly traded corporation. The Turner family members, who are disqualified persons, collectively own 15% of the same corporation. Apply Section 4943 to determine whether excess holdings exist and the amount subject to the excise tax.', '["No excess holdings exist because the foundation owns less than 20% individually", "No excess holdings exist because the combined 27% does not exceed a 35% threshold", "Combined holdings are 27%, exceeding the 20% permitted level by 7%, and the excess is subject to a 10% excise tax", "The foundation must divest all 12% because any stock ownership by a private foundation is prohibited"]'::jsonb, 2, 'Under IRC Section 4943, a private foundation and its disqualified persons may not together hold more than 20% of the voting stock of a business enterprise. The foundation (12%) plus disqualified persons (15%) totals 27%, exceeding the 20% limit by 7%. The 10% initial excise tax applies to the value of the excess holdings. Unlike choice A, the test combines foundation and disqualified person holdings — the foundation cannot be evaluated in isolation.', 'medium', 3),

-- Q18: medium / L3 — NOL deduction for UBIT computed using only UBI items
(3, 'Tax-Exempt Organizations', 'Lakeside Conservation Trust, a 501(c)(3), had $40,000 of unrelated business income and $55,000 of directly connected expenses from its parking lot in 2025, creating a $15,000 net operating loss. In 2026, the parking lot generates $30,000 of net unrelated business income before any NOL carryforward. Apply the UBIT rules to determine how the 2025 loss affects the 2026 computation.', '["The 2025 NOL cannot be carried forward because tax-exempt organizations are not allowed NOL deductions", "The $15,000 NOL carries forward, reducing 2026 UBIT to $15,000 before the $1,000 specific deduction, resulting in $14,000 of taxable UBI", "The $15,000 NOL can offset any income the trust earns including investment income and contributions", "The trust must amend its 2025 return to claim a refund rather than carry the loss forward"]'::jsonb, 1, 'Under IRC Section 512(b)(6), a net operating loss deduction is allowed for UBIT purposes, but it is computed using only unrelated business income items. The $15,000 NOL from 2025 carries forward to 2026, reducing $30,000 net UBI to $15,000. After the $1,000 specific deduction, taxable UBI is $14,000. Unlike choice C, the UBIT NOL can only offset other unrelated business income and cannot reduce investment income or contributions.', 'medium', 3),

-- Q19: hard / L4 — Section 4941 second-tier tax if self-dealing not corrected
(3, 'Tax-Exempt Organizations', 'Whitfield Arts Foundation, a private foundation, leases office space to its founder for $3,000 per month at fair market value. The IRS identifies the lease as self-dealing under Section 4941 and assesses the initial tax. The founder refuses to terminate the lease during the correction period. The foundation manager knowingly approved the lease. Evaluate the full excise tax consequences when the self-dealing is not corrected.', '["Only the initial 10% tax on the founder applies because FMV self-dealing does not trigger additional penalties", "The foundation loses its exempt status but no additional excise taxes are imposed", "The 10% initial tax is waived because the lease was at fair market value", "The founder faces a 200% additional tax on the amount involved, and the manager faces a 50% additional tax up to $20,000 for refusing to agree to correction"]'::jsonb, 3, 'Under IRC Section 4941, the initial tax on the self-dealer is 10% and 5% on any knowing manager. If not corrected within the taxable period, the self-dealer faces an additional 200% tax on the amount involved, and the manager faces an additional 50% tax (capped at $20,000). Unlike choice A, self-dealing is based on the nature of the transaction — leasing between a foundation and disqualified person is prohibited regardless of FMV, and failure to correct triggers severe second-tier penalties.', 'hard', 4),

-- Q20: easy / L1 — One-third support test for public charity classification
(3, 'Tax-Exempt Organizations', 'What does the one-third support test under Section 509(a)(1) determine?', '["Whether an organization qualifies as a public charity based on receiving substantial public or government support", "Whether a private foundation has met its 5% minimum distribution requirement", "Whether lobbying expenditures exceed the substantial part test", "Whether unrelated business income exceeds one-third of total revenue"]'::jsonb, 0, 'Under IRC Section 509(a)(1), the one-third support test determines whether a 501(c)(3) organization qualifies as a public charity rather than a private foundation. An organization meeting this test receives a substantial part of its support from the general public or government sources. Unlike choice B, the one-third support test relates to public charity classification, not the 5% minimum distribution requirement for private foundations under Section 4942.', 'easy', 1),

-- Q21: hard / L4 — Private foundation lobbying as taxable expenditure under Section 4945
(3, 'Tax-Exempt Organizations', 'Greenleaf Environmental Foundation, a private foundation, spends $75,000 on grassroots lobbying to influence state water quality legislation. The executive director argues that environmental advocacy is central to the foundation''s charitable mission. Evaluate whether this expenditure triggers penalties under Section 4945 and whether the charitable purpose provides a defense.', '["No penalty applies because environmental advocacy overrides the lobbying restriction for private foundations", "The expenditure is subject only to the 1.39% net investment income tax under Section 4940", "The $75,000 is a taxable expenditure under Section 4945, subject to a 20% tax on the foundation and 5% on the knowing manager, regardless of charitable mission", "The Section 501(h) expenditure test allows the foundation to lobby within the nontaxable amount"]'::jsonb, 2, 'Under IRC Section 4945(d)(1), any amount paid by a private foundation to influence legislation is a taxable expenditure, subject to a 20% initial tax on the foundation ($15,000) and 5% on any knowing manager ($3,750). Unlike choice A, the charitable purpose provides no defense — Section 4945 imposes a strict prohibition on lobbying by private foundations. Unlike choice D, the Section 501(h) election is available only to public charities, not private foundations.', 'hard', 4),

-- Q22: medium / L2 — Penalties for late filing of Form 990
(3, 'Tax-Exempt Organizations', 'Willowbrook Youth League, a 501(c)(3) with $350,000 in annual gross receipts, files its 2025 Form 990 seventy-five days late without reasonable cause. What penalty does Willowbrook face for late filing?', '["No penalty because tax-exempt organizations are exempt from late filing penalties", "$20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts", "A flat penalty of $500 for any late filing regardless of duration", "Automatic revocation of tax-exempt status for filing more than 60 days late"]'::jsonb, 1, 'Under IRC Section 6652(c)(1)(A), tax-exempt organizations with gross receipts under $1,186,000 face a penalty of $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts. For Willowbrook, the daily penalty totals $1,500 ($20 x 75 days), which is below both caps. Unlike choice D, automatic revocation requires three consecutive years of complete non-filing, not a single late filing.', 'medium', 2),

-- Q23: easy / L1 — Churches, schools, and hospitals as automatic public charities
(3, 'Tax-Exempt Organizations', 'How are churches, schools, and hospitals classified under Section 501(c)(3)?', '["As private foundations subject to Sections 4940-4945 excise taxes", "As social welfare organizations under Section 501(c)(4)", "As tax-exempt but required to pass the one-third support test annually", "As public charities automatically, regardless of their funding sources"]'::jsonb, 3, 'Under IRC Section 509(a)(1), churches, schools, and hospitals are automatically classified as public charities without needing to satisfy the one-third public support test or any other financial support requirement. Unlike choice C, these organizations receive automatic public charity status by virtue of their institutional type, not their funding patterns. This exempts them from private foundation excise taxes and operational restrictions.', 'easy', 1),

-- Q24: medium / L2 — Form 8868 automatic six-month extension
(3, 'Tax-Exempt Organizations', 'Pinecrest Animal Rescue, a calendar-year 501(c)(3), realizes in April 2026 that it cannot complete its Form 990 by the May 15 deadline. The accountant files Form 8868 before the due date. What extension does Form 8868 provide?', '["An automatic six-month extension, moving the deadline to November 15, 2026", "A three-month extension requiring IRS approval before being granted", "A 30-day extension available only to organizations with gross receipts under $200,000", "No extension is available because tax-exempt organizations must always file by the original deadline"]'::jsonb, 0, 'Under IRC Section 6081 and Form 8868 instructions, tax-exempt organizations may obtain an automatic six-month extension by filing Form 8868 before the original due date. For Pinecrest, this moves the deadline from May 15 to November 15, 2026. Unlike choice B, the extension is automatic and requires no IRS approval. The organization simply files Form 8868 by the original deadline to receive the full six-month extension.', 'medium', 2),

-- Q25: hard / L4 — Organization manager tax under Section 4958 and rebuttable presumption
(3, 'Tax-Exempt Organizations', 'Crestview Medical Center, a 501(c)(3) hospital, pays its CEO $1,800,000 annually when comparable compensation is $1,000,000, creating an $800,000 excess benefit. Three board members approved the arrangement knowing it was above market, without obtaining an independent comparability study. Evaluate the excise tax exposure for each knowing board member and how the rebuttable presumption of reasonableness could have changed the outcome.', '["Each board member faces a 25% tax on the $800,000 excess totaling $200,000 per member", "Board members face no personal liability because only the CEO is subject to intermediate sanctions", "Each knowing board member faces a 10% tax on the excess benefit capped at $20,000; obtaining an independent comparability study would have created a rebuttable presumption shifting the burden to the IRS", "Each board member faces joint and several liability for the full 200% additional tax"]'::jsonb, 2, 'Under IRC Section 4958(a)(2), organization managers who knowingly participate in an excess benefit transaction face a 10% excise tax on the excess benefit, capped at $20,000 per transaction. Each knowing board member owes $20,000 (10% of $800,000 = $80,000, capped). Had the board obtained independent comparability data and documented its decision, the rebuttable presumption would have shifted the burden of proof to the IRS. Unlike choice A, the 25% tax applies only to the disqualified person (CEO), not managers.', 'hard', 4),

-- Q26: medium / L3 — Private foundation presumption for all 501(c)(3) organizations
(3, 'Tax-Exempt Organizations', 'Nova Literary Society receives its 501(c)(3) determination letter. The organization is funded primarily by investment returns from a single donor''s endowment and has not applied for public charity classification. The board assumes it is a public charity because it provides free literary programs to the community. Evaluate the board''s assumption.', '["The board is correct because providing free programs qualifies the organization as a public charity", "The organization is classified as a 501(c)(4) social welfare organization", "The organization qualifies as a public charity under the convenience exclusion", "The board is incorrect because all 501(c)(3) organizations are presumed to be private foundations unless they affirmatively demonstrate public charity status"]'::jsonb, 3, 'Under IRC Section 509(a), all 501(c)(3) organizations are presumed to be private foundations unless they affirmatively demonstrate qualification as a public charity under a statutory exception (one-third support test, supporting organization, or institutional type). Nova, funded by a single donor''s endowment, likely cannot meet the public support tests. Unlike choice A, providing charitable programs does not override the private foundation presumption — affirmative classification is required.', 'medium', 3),

-- Q27: easy / L1 — Operational test requirement
(3, 'Tax-Exempt Organizations', 'What does the operational test require a 501(c)(3) organization to demonstrate?', '["That the organization is operated primarily for one or more exempt purposes", "That the organization earns no revenue from any source", "That the organization has fewer than 100 employees", "That the organization receives at least 50% of support from government grants"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily for exempt purposes such as charitable, educational, religious, or scientific activities. The organization must engage primarily in activities that accomplish these purposes. Unlike choice D, the operational test does not impose a specific funding source requirement — it focuses on whether actual activities further exempt purposes, not where revenue originates.', 'easy', 1),

-- Q28: easy / L2 — Section 509(a)(2) gross receipts test for public charity
(3, 'Tax-Exempt Organizations', 'Maple Street Community Theater, a 501(c)(3), normally receives 40% of its support from ticket sales related to its educational mission and 25% from membership fees. It receives 20% from a single large donor and 15% from investment income. Under Section 509(a)(2), does Maple Street qualify as a public charity?', '["No, because it receives more than one-third of support from a single donor", "Yes, because it normally receives more than one-third from contributions, membership fees, and gross receipts from exempt-function activities", "No, because investment income disqualifies an organization from public charity status", "Yes, but only if it also meets the Section 509(a)(1) one-third public support test"]'::jsonb, 1, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if it normally receives more than one-third of support from contributions, membership fees, and gross receipts from exempt-function activities. Maple Street receives 40% from exempt-function ticket sales plus 25% from membership fees, totaling 65%, which exceeds the one-third threshold. Unlike choice A, having a single large donor does not disqualify the organization under the 509(a)(2) test when exempt-function receipts are sufficient.', 'easy', 2),

-- Q29: medium / L2 — Schedule A of Form 990 reports public charity status
(3, 'Tax-Exempt Organizations', 'Harmony Education Alliance, a 501(c)(3) public charity, is preparing its annual Form 990. The accountant must complete Schedule A. What information does Schedule A of Form 990 report?', '["Compensation paid to officers, directors, and key employees", "All contributors who gave more than $5,000 during the year", "The organization''s investment portfolio and endowment activity", "The organization''s public charity status and public support calculations"]'::jsonb, 3, 'Schedule A of Form 990 reports the organization''s public charity classification and includes detailed public support calculations demonstrating continued qualification under the applicable test (Section 509(a)(1) or 509(a)(2)). Unlike choice A, compensation information is reported on Schedule J, not Schedule A. Contributor details are reported on the confidential Schedule B, which is not publicly available.', 'medium', 2),

-- Q30: medium / L2 — Schedule J compensation reporting on Form 990
(3, 'Tax-Exempt Organizations', 'Ridgeview Health Services, a 501(c)(3) hospital, must complete Schedule J of its Form 990 for 2025. The hospital employs a CEO earning $750,000, a CFO earning $400,000, and a medical director earning $600,000. What does Schedule J require the organization to report?', '["Only the CEO''s compensation because Schedule J covers the single highest-paid individual", "All investment income and portfolio returns earned by the organization", "Detailed compensation for officers, directors, and key employees including base pay, bonus, and other compensation", "The organization''s lobbying and political expenditures for the tax year"]'::jsonb, 2, 'Schedule J of Form 990 requires detailed compensation reporting for officers, directors, trustees, and key employees, including base compensation, bonus and incentive pay, other reportable compensation, retirement and deferred compensation, and nontaxable benefits. Unlike choice A, Schedule J covers all listed individuals meeting the reporting threshold, not just the highest-paid. This transparency helps evaluate reasonableness under Section 4958 intermediate sanctions.', 'medium', 2)
;

COMMIT;
